import sys

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    edges = []
    adj = [[] for _ in range(N)]
    for _ in range(M):
        s, t = map(int, input().split())
        s -= 1
        t -= 1
        edges.append((s, t))
        adj[s].append(t)

    # First compute base expected values without blocking
    INF = 10**18

    def compute_expected(block_edge=None):
        # block_edge = (u,v) to block, or None
        out_deg = [0]*N
        g = [[] for _ in range(N)]
        for s, t in edges:
            if block_edge is not None and (s, t) == block_edge:
                continue
            g[s].append(t)
            out_deg[s] += 1
        # Check reachability to N-1 from all nodes
        from collections import deque
        reachable = [False]*N
        dq = deque()
        dq.append(N-1)
        reachable[N-1] = True
        while dq:
            v = dq.popleft()
            for u in range(N):
                if not reachable[u]:
                    for w in g[u]:
                        if w == v:
                            reachable[u] = True
                            dq.append(u)
                            break
        for v in range(N-1):
            if out_deg[v] > 0 and not reachable[v]:
                return INF  # invalid block

        # expected steps from each node to N-1
        E = [0.0]*N
        # process in reverse topological order (since edges go from smaller to larger index)
        for v in range(N-2, -1, -1):
            if out_deg[v] == 0:
                continue
            s = 0.0
            for w in g[v]:
                s += E[w]
            E[v] = 1.0 + s / out_deg[v]
        return E[0]

    best = compute_expected()
    for s, t in edges:
        if s == 0 or t == N-1:
            # blocking edges from start or to exit might be interesting
            val = compute_expected((s, t))
            if val < best:
                best = val
        # Also consider blocking any edge that might reduce expectation
        val = compute_expected((s, t))
        if val < best:
            best = val

    print(f"{best:.10f}")

if __name__ == "__main__":
    solve()

import sys
from fractions import Fraction

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx+=1
    M = int(input_data[idx]); idx+=1

    edges = []
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        s = int(input_data[idx]); idx+=1
        t = int(input_data[idx]); idx+=1
        edges.append((s,t))
        adj[s].append(t)

    def compute_E(blocked=None):
        E = [0.0] * (N+1)
        # Process from N-1 down to 1
        for v in range(N-1, 0, -1):
            neighbors = [t for t in adj[v] if (v,t) != blocked]
            if not neighbors:
                return None  # invalid
            E[v] = 1.0 + sum(E[t] for t in neighbors) / len(neighbors)
        return E[1]

    # Check if blocking an edge is valid: all rooms must still reach N
    def can_reach_N(blocked=None):
        reach = [False] * (N+1)
        reach[N] = True
        for v in range(N-1, 0, -1):
            for t in adj[v]:
                if (v,t) != blocked and reach[t]:
                    reach[v] = True
                    break
        return all(reach[v] for v in range(1, N))

    best = compute_E(None)

    for (s,t) in edges:
        if can_reach_N((s,t)):
            val = compute_E((s,t))
            if val is not None and val < best:
                best = val

    print(f"{best:.10f}")

solve()
